namespace Aster {
static class PlayColors {
 public static Color Primary(string theme){return theme=="Tide"?Color.FromArgb(64,223,193):theme=="Sunset"?Color.FromArgb(255,172,123):Color.FromArgb(182,147,255);}
 public static Color Deep(string theme){return theme=="Tide"?Color.FromArgb(14,65,75):theme=="Sunset"?Color.FromArgb(89,40,73):Color.FromArgb(50,37,94);}
 public static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
class AuroraHeader:Panel {
 public string ThemeName="Nebula";
 public AuroraHeader(){DoubleBuffered=true;}
 protected override void OnPaintBackground(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;if(Width<2||Height<2)return;using(var shape=PlayColors.Round(new RectangleF(0,0,Width-1,Height-1),16))using(var b=new LinearGradientBrush(ClientRectangle,ThemePalette.Current.Hero,ThemePalette.Current.Surface,15f))g.FillPath(b,shape);for(int i=0;i<4;i++){using(var p=new Pen(Color.FromArgb(22,ThemePalette.Current.Accent),12))g.DrawBezier(p,Width*.50f+i*20,Height+20,Width*.68f,-70,Width*.78f,Height+50,Width+30,-10);}}
}
class SessionCountdown {
 public TimeSpan Remaining{get;private set;}public bool Running{get;private set;}public int Completed{get;private set;}public TimeSpan Duration{get;private set;}TimeSpan anchor;
 public SessionCountdown(){Reset(25);}
 public void Reset(int minutes){Running=false;Duration=Remaining=TimeSpan.FromMinutes(Math.Max(1,Math.Min(180,minutes)));}
 public void Start(TimeSpan now){if(Remaining<=TimeSpan.Zero)return;anchor=now;Running=true;}
 public bool Update(TimeSpan now){if(!Running)return false;var delta=now-anchor;anchor=now;if(delta<TimeSpan.Zero)delta=TimeSpan.Zero;Remaining-=delta;if(Remaining<=TimeSpan.Zero){Remaining=TimeSpan.Zero;Running=false;Completed++;return true;}return false;}
 public bool Pause(TimeSpan now){bool done=Update(now);Running=false;return done;}
}
class OrbitCanvas:Control {
 public string ThemeName="Nebula",Scene="Orbit";public double Cpu,Ram;public bool HasData;public double Phase;public string CenterTitle="ASTER",CenterValue="SYSTEM PLAYGROUND";public bool TimerMode;public double Progress;
 class Spark{public float X,Y,Vx,Vy;public int Life;}
 List<Spark> sparks=new List<Spark>();Random random=new Random(47);public bool Motion=true;
 public OrbitCanvas(){DoubleBuffered=true;Dock=DockStyle.Fill;BackColor=Color.FromArgb(14,19,31);Cursor=Cursors.Cross;SetStyle(ControlStyles.ResizeRedraw,true);}
 public void Celebrate(){if(Motion)Burst(Width/2,Height/3);}
 void Burst(int x,int y){for(int i=0;i<22;i++){double a=random.NextDouble()*Math.PI*2;sparks.Add(new Spark{X=x,Y=y,Vx=(float)Math.Cos(a)*4,Vy=(float)Math.Sin(a)*4,Life=45});}if(sparks.Count>88)sparks.RemoveRange(0,sparks.Count-88);}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(Motion)Burst(e.X,e.Y);else{Phase+=.4;Invalidate();}}
 public void Advance(){if(Motion){Phase+=.022;foreach(var s in sparks){s.X+=s.Vx;s.Y+=s.Vy;s.Vy+=.045f;s.Life--;}sparks.RemoveAll(s=>s.Life<=0);}else sparks.Clear();Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Width<10||Height<10)return;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;Color color=PlayColors.Primary(ThemeName);using(var bg=new LinearGradientBrush(ClientRectangle,Color.FromArgb(14,19,31),PlayColors.Deep(ThemeName),60f))g.FillRectangle(bg,ClientRectangle);for(int i=0;i<55;i++){float x=(i*173%997)/997f*Width,y=(i*97%509)/509f*Height;int a=60+(int)(35*(1+Math.Sin(Phase+i)));using(var b=new SolidBrush(Color.FromArgb(a,195,215,250)))g.FillEllipse(b,x,y,i%4==0?3:1.5f,i%4==0?3:1.5f);}
 float cx=Width/2f,cy=Height*.46f,r=Math.Min(Width,Height)*.24f;
 if(Scene=="Aurora"){for(int layer=0;layer<5;layer++){var points=new List<PointF>();for(int x=0;x<=Width;x+=8)points.Add(new PointF(x,(float)(Height*.50+Math.Sin(x*.009+Phase+layer*.4)*(40+Cpu*.5)+layer*23)));using(var pen=new Pen(Color.FromArgb(45+layer*12,color),12))g.DrawLines(pen,points.ToArray());}}
 else if(Scene=="Pixel garden"){for(int i=0;i<20;i++){float x=Width*(i+1)/21f;float h=(float)(35+(1+Math.Sin(i*.7+Phase))*(40+Cpu*.65));for(int j=0;j<h/12;j++)using(var b=new SolidBrush(Color.FromArgb(70+Math.Min(150,j*8),color)))g.FillRectangle(b,x-7,Height-40-j*12,9,9);}}
 else{for(int i=0;i<3;i++){float radius=r+i*24;using(var p=new Pen(Color.FromArgb(35+i*12,color),1))g.DrawEllipse(p,cx-radius,cy-radius*.67f,radius*2,radius*1.34f);double angle=Phase*(.45+Cpu/160)+i*2;float px=cx+(float)Math.Cos(angle)*radius,py=cy+(float)Math.Sin(angle)*radius*.67f;using(var b=new SolidBrush(i==1?Color.FromArgb(103,227,221):color))g.FillEllipse(b,px-6,py-6,12,12);}}
 using(var b=new SolidBrush(Color.FromArgb(210,18,25,42)))g.FillEllipse(b,cx-r*.68f,cy-r*.68f,r*1.36f,r*1.36f);if(TimerMode){using(var p=new Pen(Color.FromArgb(55,color),5))g.DrawEllipse(p,cx-r*.68f,cy-r*.68f,r*1.36f,r*1.36f);if(Progress>0)using(var p=new Pen(color,5))g.DrawArc(p,cx-r*.68f,cy-r*.68f,r*1.36f,r*1.36f,-90,(float)(360*Math.Min(1,Progress)));}
 using(var f=new Font("Segoe UI",TimerMode?30:23,FontStyle.Bold))TextRenderer.DrawText(g,CenterTitle,f,new Rectangle((int)(cx-r),(int)cy-35,(int)(r*2),52),Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);using(var f=new Font("Segoe UI",9))TextRenderer.DrawText(g,CenterValue,f,new Rectangle((int)(cx-r-60),(int)cy+21,(int)(r*2+120),30),color,TextFormatFlags.HorizontalCenter|TextFormatFlags.NoPrefix);
 if(!TimerMode){string reading=HasData?"CPU "+Cpu.ToString("F1")+"%     •     RAM "+Ram.ToString("F1")+"%":"Waiting for a real system sample";using(var f=new Font("Segoe UI",13))TextRenderer.DrawText(g,reading,f,new Rectangle(12,Height-75,Width-24,30),Color.White,TextFormatFlags.HorizontalCenter);using(var f=new Font("Segoe UI",9))TextRenderer.DrawText(g,"Decorative motion follows CPU load · not a benchmark · click for stardust",f,new Rectangle(12,Height-38,Width-24,25),Color.FromArgb(170,190,215),TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);}
 foreach(var s in sparks)using(var b=new SolidBrush(Color.FromArgb(Math.Min(255,s.Life*5),color)))g.FillEllipse(b,s.X,s.Y,5,5);
 }
}
partial class MainWindow {
 Timer funClock;Stopwatch funTime=new Stopwatch();SessionCountdown countdown=new SessionCountdown();OrbitCanvas funCanvas;Label timerState;Button timerStart;NumericUpDown timerMinutes;bool timerDone;
 void SetupFun(){funTime.Start();funClock=new Timer{Interval=1000};funClock.Tick+=(s,e)=>TickFun();funClock.Start();Resize+=(s,e)=>ConfigureFun();FormClosed+=(s,e)=>{funClock.Dispose();funTime.Stop();};}
 void ConfigureFun(){if(funClock!=null)funClock.Interval=(page=="Playground"||page=="Focus timer")&&preferences.Motion&&WindowState!=FormWindowState.Minimized?50:1000;}
 void TickFun(){if(countdown.Update(funTime.Elapsed)){timerDone=true;if(funCanvas!=null&&!funCanvas.IsDisposed&&page=="Focus timer")funCanvas.Celebrate();}if(WindowState==FormWindowState.Minimized)return;if(funCanvas!=null&&!funCanvas.IsDisposed&&(page=="Playground"||page=="Focus timer")){funCanvas.Motion=preferences.Motion;funCanvas.ThemeName=preferences.PlayTheme;if(current!=null){funCanvas.Cpu=current.Cpu;funCanvas.Ram=current.MemoryPercent;funCanvas.HasData=true;}if(page=="Focus timer"){double seconds=Math.Ceiling(countdown.Remaining.TotalSeconds);funCanvas.CenterTitle=((int)seconds/60).ToString("00")+":"+((int)seconds%60).ToString("00");funCanvas.CenterValue=timerDone?"NICE WORK. TAKE A BREATH.":countdown.Running?"ONE THING AT A TIME":"YOUR MOMENT TO FOCUS";funCanvas.Progress=1-countdown.Remaining.TotalSeconds/countdown.Duration.TotalSeconds;timerState.Text=(timerDone?"Session complete! ":countdown.Running?"Running · ":"Ready / paused · ")+countdown.Completed+" completed this session. Timer continues while you browse Aster.";timerStart.Text=countdown.Running?"Pause":"Start / resume";timerMinutes.Enabled=!countdown.Running;}funCanvas.Advance();}}
 FlowLayoutPanel PlayControls(){var controls=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};var label=new Label{Text="PALETTE",AutoSize=true,ForeColor=muted,Margin=new Padding(0,10,10,0)};controls.Controls.Add(label);var theme=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=145};theme.Items.AddRange(new[]{"Nebula","Tide","Sunset"});theme.SelectedItem=theme.Items.Contains(preferences.PlayTheme)?preferences.PlayTheme:"Nebula";theme.SelectedIndexChanged+=(s,e)=>{preferences.PlayTheme=(string)theme.SelectedItem;preferences.Accent=preferences.PlayTheme=="Tide"?"Mint":preferences.PlayTheme=="Nebula"?"Violet":"Sunset";SavePreferences();StyleView();TickFun();};controls.Controls.Add(theme);var motion=new CheckBox{Text="Animate scenes",AutoSize=true,Checked=preferences.Motion,Margin=new Padding(16,8,12,0)};motion.CheckedChanged+=(s,e)=>{preferences.Motion=motion.Checked;SavePreferences();ConfigureFun();TickFun();};controls.Controls.Add(motion);return controls;}
 void BuildPlayground(){sub.Text="A playful window into your system · powered by your existing readings";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};root.RowStyles.Add(new RowStyle(SizeType.Absolute,82));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);var controls=PlayControls();root.Controls.Add(controls,0,0);var scenes=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=150};scenes.Items.AddRange(new[]{"Orbit","Aurora","Pixel garden"});scenes.SelectedIndex=0;controls.Controls.Add(scenes);var timerButton=Button("Start a focus session →");timerButton.Click+=(s,e)=>Navigate("Focus timer");controls.Controls.Add(timerButton);funCanvas=new OrbitCanvas{ThemeName=preferences.PlayTheme,Motion=preferences.Motion};root.Controls.Add(funCanvas,0,1);scenes.SelectedIndexChanged+=(s,e)=>{funCanvas.Scene=(string)scenes.SelectedItem;funCanvas.Invalidate();};TickFun();}
 void BuildFocusTimer(){sub.Text="A gentle countdown · no blocked apps, automatic settings changes, or sounds";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};root.RowStyles.Add(new RowStyle(SizeType.Absolute,58));root.RowStyles.Add(new RowStyle(SizeType.Absolute,58));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));content.Controls.Add(root);root.Controls.Add(PlayControls(),0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(actions,0,1);actions.Controls.Add(new Label{Text="Minutes",AutoSize=true,Margin=new Padding(0,8,8,0)});timerMinutes=new NumericUpDown{Minimum=1,Maximum=180,Value=(decimal)countdown.Duration.TotalMinutes,Width=72};actions.Controls.Add(timerMinutes);timerStart=Button("Start / resume");timerStart.Click+=(s,e)=>{if(countdown.Running){if(countdown.Pause(funTime.Elapsed))timerDone=true;}else{if(countdown.Remaining==TimeSpan.Zero||countdown.Duration.TotalMinutes!=(double)timerMinutes.Value)countdown.Reset((int)timerMinutes.Value);timerDone=false;countdown.Start(funTime.Elapsed);}TickFun();};actions.Controls.Add(timerStart);var reset=Button("Reset");reset.Click+=(s,e)=>{countdown.Reset((int)timerMinutes.Value);timerDone=false;TickFun();};actions.Controls.Add(reset);foreach(int minutes in new[]{5,25,50}){int duration=minutes;var preset=Button(minutes==5?"5m break":minutes+"m focus");preset.Click+=(s,e)=>{countdown.Reset(duration);timerMinutes.Value=duration;timerDone=false;TickFun();};actions.Controls.Add(preset);}funCanvas=new OrbitCanvas{TimerMode=true,ThemeName=preferences.PlayTheme,Motion=preferences.Motion};root.Controls.Add(funCanvas,0,2);timerState=new Label{Dock=DockStyle.Fill,ForeColor=muted,Padding=new Padding(0,12,0,0)};root.Controls.Add(timerState,0,3);TickFun();}
}
}


